typedef unsigned int nlUint32;
typedef unsigned int nslEmitterId;
typedef float nlVector3d[3];

struct fifo_queue
{
  int data[3];
};

struct nslEmitter
{
  bool used;
  bool autoRelease;
  bool isALineEmitter;
  nslEmitterId myId;
  nlVector3d startPosition;
  nlVector3d endPosition;
  nlVector3d position;
  fifo_queue emittedSounds;
};

struct nslSystem
{
  char padding[0x11840];
  nslEmitter emitterSlots[256];
  nlUint32 sourceSlotsUsedCount;
  nlUint32 soundSlotsUsedCount;
  nlUint32 emitterSlotsUsedCount;
  int firstInit;
  int initialized;
  nlUint32 numBanks;
  char state[32];
  bool on;
};

enum _nslClearBehaviour
{
  NSL_CLEAR_INIT,
  NSL_CLEAR_RESET,
  NSL_CLEAR_FREE
};

extern nslSystem nsl;
extern const char nsl_not_initialized[];
extern "C" void *memcpy(void *, const void *, unsigned int);
void nslFatal(const char *, ...);
void _nslClearEmitterSlot(nlUint32, bool, _nslClearBehaviour);

__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ nsl_not_initialized, 0x0051C2F0");
__asm__(".equ nslFatal__FPCce, 0x00391420");
__asm__(".equ _nslClearEmitterSlot__FUib18_nslClearBehaviour, 0x003910A0");

#define NSL_NUM_EMITTERS 256
#define NSL_ID_INCREMENT 0x00000400
#define NSL_INVALID_ID 0
#define ASSERT_NSL_INITIALIZED() \
  do { if (!(nsl.initialized == 1)) nslFatal(nsl_not_initialized); } while (0)

nslEmitterId nslCreateEmitter( const nlVector3d &position )
{
  if (!nsl.on) return 1;
  ASSERT_NSL_INITIALIZED();
  for (int i=0; i < NSL_NUM_EMITTERS; i++) 
  {
    if (!nsl.emitterSlots[i].used) 
    {
      _nslClearEmitterSlot(i, false, NSL_CLEAR_RESET);
      nsl.emitterSlots[i].used = true;
      nsl.emitterSlots[i].autoRelease = false;
      nsl.emitterSlots[i].isALineEmitter = false;
      nsl.emitterSlotsUsedCount++;
      memcpy(nsl.emitterSlots[i].position, position, sizeof(nlVector3d));
      /*nsl.emitterSlots[i].position[0] = position[0];
      nsl.emitterSlots[i].position[1] = position[1];
      nsl.emitterSlots[i].position[2] = position[2];*/
      nsl.emitterSlots[i].myId += NSL_ID_INCREMENT;
      return nsl.emitterSlots[i].myId;
    }
  }
  return NSL_INVALID_ID;
}
